    inside_4: 'रफ़्तार से भाग दें। मान लीजिए किसी हमलावर ने उलझाए हुए पासवर्ड की फ़ाइल चुरा ली है और ताक़तवर ग्राफ़िक्स कार्ड से हर सेकंड 10 अरब अंदाज़े लगा रहा है। वेबसाइटें कुछ ग़लत कोशिशों के बाद रोक देती हैं, पर चोरी हुई फ़ाइल पर पूरी रफ़्तार से हमला हो सकता है।',
    inside_5: 'यह सिर्फ़ एक अनुमान है। हमारी शब्द-सूचियाँ छोटी हैं, इसलिए जिन शब्दों को हम नहीं जानते (और भारतीय लिपियों में लिखे शब्द), वे असल से ज़्यादा मज़बूत दिख सकते हैं।',
