    tip2_t: 'लंबाई चालाकी से बेहतर', tip2_d: '5 या ज़्यादा बेतरतीब शब्द, या 12+ बेतरतीब अक्षर रखें। अक्षरों को चिह्नों से बदलने से ज़्यादा लंबाई मायने रखती है।',
    tip3_t: 'पासवर्ड मैनेजर अपनाएँ', tip3_d: 'पासवर्ड मैनेजर (जैसे आपके फ़ोन या ब्राउज़र में बना हुआ) मज़बूत पासवर्ड याद रखता है। आपको बस एक मज़बूत पासफ़्रेज़ याद रखना है।',
    tip4_t: '2-स्टेप वेरिफ़िकेशन चालू करें', tip4_d: 'तब सिर्फ़ चोरी हुआ पासवर्ड काफ़ी नहीं होता। इसे ईमेल, WhatsApp (टू-स्टेप PIN), Instagram और दूसरे ज़रूरी अकाउंट पर चालू करें।',
    tip5_t: 'OTP कभी शेयर न करें', tip5_d: 'बैंक कर्मचारी, पुलिस, डिलीवरी वाले या “कस्टमर केयर” कभी आपका OTP, PIN या पासवर्ड नहीं माँगते। जो माँगे, वह धोखेबाज़ है।',
