    tip7_t: 'साझा कंप्यूटर पर सावधान', tip7_d: 'साइबर कैफ़े या कंप्यूटर लैब में “पासवर्ड याद रखें” पर टिक न करें, और हमेशा लॉग आउट करें।',
    tip8_t: 'लीक के बाद बदलें', tip8_d: 'अगर कोई वेबसाइट बताए कि उसका डेटा लीक हुआ है, या आपने किसी को पासवर्ड बता दिया, तो उसे तुरंत हर उस जगह बदलें जहाँ इस्तेमाल किया था।',
