    inside_title: 'ভেতরে কী হচ্ছে?',
    inside_1: 'বিকল্প গোনো। ছোট হাতের অক্ষরে প্রতিটি জায়গায় 26টি বিকল্প; বড় হাতের অক্ষর, সংখ্যা আর চিহ্ন মিলিয়ে 95টি পর্যন্ত। সোজা অঙ্কে প্রতিটি অক্ষরের জন্য বিকল্পগুলো একবার করে গুণ হয়।',
    inside_2: 'প্যাটার্ন চেনো। আসল আক্রমণকারীরা এলোমেলো আন্দাজ করে না। আগে তারা ফাঁস হওয়া সাধারণ পাসওয়ার্ড, শব্দ, নাম, তারিখ, কিবোর্ডের লাইন (qwerty), ক্রম (1234), পুনরাবৃত্তি আর একই রকম দেখতে বদল (p@ssw0rd) চেষ্টা করে। এই অ্যাপও এই প্যাটার্নগুলো খোঁজে।',
    inside_3: 'গুণ করো। প্রতিটি টুকরোর আন্দাজ একসঙ্গে গুণ হয়। “বিট” এগুলো গোনার ছোট উপায়: প্রতিটি বাড়তি বিটে আন্দাজ দ্বিগুণ হয়।',
    inside_4: 'গতি দিয়ে ভাগ করো। ধরো কোনো আক্রমণকারী এলোমেলো করে রাখা পাসওয়ার্ডের ফাইল চুরি করেছে আর শক্তিশালী গ্রাফিক্স কার্ড দিয়ে প্রতি সেকেন্ডে 1000 কোটি আন্দাজ করছে। ওয়েবসাইট কয়েকটা ভুল চেষ্টার পরে আটকে দেয়, কিন্তু চুরি করা ফাইলে পুরো গতিতে আক্রমণ চলে।',
    inside_5: 'এটা শুধু একটা আনুমানিক হিসাব। আমাদের শব্দের তালিকা ছোট, তাই যে শব্দ আমরা জানি না (আর ভারতীয় লিপিতে লেখা শব্দ), সেগুলো আসলের চেয়ে বেশি শক্তিশালী দেখাতে পারে।',
