    tip4_t: '2-ধাপ যাচাই চালু করো', tip4_d: 'তখন শুধু চুরি করা পাসওয়ার্ড যথেষ্ট নয়। ইমেল, WhatsApp (টু-স্টেপ PIN), Instagram আর অন্য জরুরি অ্যাকাউন্টে এটা চালু করো।',
    tip5_t: 'কখনো OTP শেয়ার কোরো না', tip5_d: 'ব্যাংকের কর্মী, পুলিশ, ডেলিভারির লোক বা “কাস্টমার কেয়ার” কখনো তোমার OTP, PIN বা পাসওয়ার্ড চায় না। যে চায়, সে প্রতারক।',
