    tip7_t: 'শেয়ার করা কম্পিউটারে সাবধান', tip7_d: 'সাইবার ক্যাফে বা কম্পিউটার ল্যাবে “পাসওয়ার্ড মনে রাখো”-তে টিক দিও না, আর সবসময় লগ আউট করো।',
    tip8_t: 'ফাঁস হলে বদলাও', tip8_d: 'কোনো ওয়েবসাইট যদি জানায় তাদের ডেটা ফাঁস হয়েছে, বা তুমি কাউকে পাসওয়ার্ড বলে ফেলেছ, তাহলে যেখানে যেখানে ব্যবহার করেছ সব জায়গায় সঙ্গে সঙ্গে বদলাও।',
