    inside_title: 'અંદર શું થાય છે?',
    inside_1: 'વિકલ્પ ગણો. નાના અક્ષરોથી દરેક જગ્યા માટે 26 વિકલ્પ મળે; મોટા અક્ષર, આંકડા અને ચિહ્નો સાથે 95 સુધી. સીધું ગણિત દરેક અક્ષર માટે વિકલ્પોનો એક વાર ગુણાકાર કરે છે.',
    inside_2: 'પેટર્ન ઓળખો. સાચા હુમલાખોરો આડેધડ અંદાજ નથી લગાવતા. પહેલાં તેઓ લીક થયેલા સામાન્ય પાસવર્ડ, શબ્દો, નામ, તારીખો, કીબોર્ડની લાઇનો (qwerty), ક્રમ (1234), પુનરાવર્તન અને મળતા આવતા ફેરફાર (p@ssw0rd) અજમાવે છે. આ ઍપ પણ આ જ પેટર્ન શોધે છે.',
    inside_3: 'ગુણાકાર કરો. દરેક ટુકડાના અંદાજનો એકબીજા સાથે ગુણાકાર થાય છે. “બિટ” તેને ગણવાની ટૂંકી રીત છે: દરેક વધારાના બિટથી અંદાજ બમણા થાય છે.',
    inside_4: 'ઝડપ વડે ભાગાકાર કરો. ધારો કે કોઈ હુમલાખોરે ગૂંચવેલા પાસવર્ડની ફાઇલ ચોરી લીધી છે અને શક્તિશાળી ગ્રાફિક્સ કાર્ડથી દર સેકન્ડે 1000 કરોડ અંદાજ લગાવે છે. વેબસાઇટ થોડા ખોટા પ્રયાસો પછી રોકી દે છે, પણ ચોરાયેલી ફાઇલ પર પૂરી ઝડપે હુમલો થઈ શકે.',
    inside_5: 'આ ફક્ત અંદાજ છે. અમારી શબ્દયાદીઓ નાની છે, એટલે જે શબ્દો અમે નથી જાણતા (અને ભારતીય લિપિમાં લખેલા શબ્દો) તે ખરેખર કરતાં વધુ મજબૂત દેખાઈ શકે.',
    scale_title: 'તાકાતનું માપ', scale_level: 'સ્તર', scale_time: 'પકડવામાં લાગતો સમય',
    scale_0: '1 કલાકથી ઓછો', scale_1: '1 કલાકથી 1 મહિનો', scale_2: '1 મહિનાથી 100 વર્ષ', scale_3: '100 વર્ષથી 1 કરોડ વર્ષ', scale_4: '1 કરોડ વર્ષથી વધુ',
    gen_title: 'પાસફ્રેઝ બનાવો',
    gen_intro: 'પાસફ્રેઝ એટલે થોડા અવ્યવસ્થિત શબ્દો જોડીને બનાવેલું વાક્ય. તે લાંબો હોય છે એટલે ધારવો અઘરો, પણ યાદ રાખવો સરળ.',
