    gen_memory_tip: 'યાદ રાખવા આ શબ્દોથી કોઈ મજેદાર ચિત્ર કે નાની વાર્તા કલ્પો.',
    gen_screen_warn: 'બીજાએ સ્ક્રીન પર જોયેલો પાસફ્રેઝ ન વાપરો. તમારો સાચો પાસફ્રેઝ એકાંતમાં બનાવો.',
