    inside_1: 'ਵਿਕਲਪ ਗਿਣੋ। ਛੋਟੇ ਅੱਖਰਾਂ ਨਾਲ ਹਰ ਥਾਂ ਲਈ 26 ਵਿਕਲਪ ਮਿਲਦੇ ਹਨ; ਵੱਡੇ ਅੱਖਰ, ਅੰਕ ਅਤੇ ਚਿੰਨ੍ਹ ਮਿਲਾ ਕੇ 95 ਤੱਕ। ਸਿੱਧਾ ਹਿਸਾਬ ਹਰ ਅੱਖਰ ਲਈ ਵਿਕਲਪਾਂ ਨੂੰ ਇੱਕ ਵਾਰ ਗੁਣਾ ਕਰਦਾ ਹੈ।',
    inside_2: 'ਪੈਟਰਨ ਪਛਾਣੋ। ਅਸਲੀ ਹਮਲਾਵਰ ਬੇਤਰਤੀਬ ਅੰਦਾਜ਼ੇ ਨਹੀਂ ਲਗਾਉਂਦੇ। ਪਹਿਲਾਂ ਉਹ ਲੀਕ ਹੋਏ ਆਮ ਪਾਸਵਰਡ, ਸ਼ਬਦ, ਨਾਂ, ਤਾਰੀਖ਼ਾਂ, ਕੀਬੋਰਡ ਦੀਆਂ ਲਾਈਨਾਂ (qwerty), ਕ੍ਰਮ (1234), ਦੁਹਰਾਅ ਅਤੇ ਮਿਲਦੇ-ਜੁਲਦੇ ਬਦਲਾਅ (p@ssw0rd) ਅਜ਼ਮਾਉਂਦੇ ਹਨ। ਇਹ ਐਪ ਵੀ ਇਹੀ ਪੈਟਰਨ ਲੱਭਦੀ ਹੈ।',
    inside_3: 'ਗੁਣਾ ਕਰੋ। ਹਰ ਟੁਕੜੇ ਦੇ ਅੰਦਾਜ਼ੇ ਆਪਸ ਵਿੱਚ ਗੁਣਾ ਹੁੰਦੇ ਹਨ। “ਬਿਟ” ਇਨ੍ਹਾਂ ਨੂੰ ਗਿਣਨ ਦਾ ਛੋਟਾ ਤਰੀਕਾ ਹੈ: ਹਰ ਵਾਧੂ ਬਿਟ ਨਾਲ ਅੰਦਾਜ਼ੇ ਦੁੱਗਣੇ ਹੋ ਜਾਂਦੇ ਹਨ।',
    inside_4: 'ਰਫ਼ਤਾਰ ਨਾਲ ਭਾਗ ਕਰੋ। ਮੰਨ ਲਓ ਕਿਸੇ ਹਮਲਾਵਰ ਨੇ ਉਲਝਾਏ ਪਾਸਵਰਡਾਂ ਦੀ ਫ਼ਾਈਲ ਚੋਰੀ ਕਰ ਲਈ ਹੈ ਅਤੇ ਤਾਕਤਵਰ ਗ੍ਰਾਫ਼ਿਕਸ ਕਾਰਡ ਨਾਲ ਹਰ ਸਕਿੰਟ 1000 ਕਰੋੜ ਅੰਦਾਜ਼ੇ ਲਗਾ ਰਿਹਾ ਹੈ। ਵੈੱਬਸਾਈਟਾਂ ਕੁਝ ਗ਼ਲਤ ਕੋਸ਼ਿਸ਼ਾਂ ਮਗਰੋਂ ਰੋਕ ਦਿੰਦੀਆਂ ਹਨ, ਪਰ ਚੋਰੀ ਹੋਈ ਫ਼ਾਈਲ ’ਤੇ ਪੂਰੀ ਰਫ਼ਤਾਰ ਨਾਲ ਹਮਲਾ ਹੋ ਸਕਦਾ ਹੈ।',
    inside_5: 'ਇਹ ਸਿਰਫ਼ ਇੱਕ ਅੰਦਾਜ਼ਾ ਹੈ। ਸਾਡੀਆਂ ਸ਼ਬਦ-ਸੂਚੀਆਂ ਛੋਟੀਆਂ ਹਨ, ਇਸ ਲਈ ਜੋ ਸ਼ਬਦ ਅਸੀਂ ਨਹੀਂ ਜਾਣਦੇ (ਅਤੇ ਭਾਰਤੀ ਲਿਪੀਆਂ ਵਿੱਚ ਲਿਖੇ ਸ਼ਬਦ), ਉਹ ਅਸਲ ਨਾਲੋਂ ਵੱਧ ਮਜ਼ਬੂਤ ਦਿਸ ਸਕਦੇ ਹਨ।',
