    tip1_t: 'ਇੱਕ ਪਾਸਵਰਡ, ਇੱਕ ਖਾਤਾ', tip1_d: 'ਜੇ ਇੱਕ ਵੈੱਬਸਾਈਟ ਹੈਕ ਹੋ ਜਾਵੇ, ਤਾਂ ਅਪਰਾਧੀ ਉਹੀ ਪਾਸਵਰਡ ਤੁਹਾਡੀ ਈਮੇਲ, ਸੋਸ਼ਲ ਮੀਡੀਆ ਅਤੇ ਬੈਂਕ ’ਤੇ ਅਜ਼ਮਾਉਂਦੇ ਹਨ। ਵੱਖ-ਵੱਖ ਪਾਸਵਰਡ ਇਸ ਨੂੰ ਰੋਕਦੇ ਹਨ।',
    tip2_t: 'ਚਲਾਕੀ ਨਾਲੋਂ ਲੰਬਾਈ ਬਿਹਤਰ', tip2_d: '5 ਜਾਂ ਵੱਧ ਬੇਤਰਤੀਬ ਸ਼ਬਦ, ਜਾਂ 12+ ਬੇਤਰਤੀਬ ਅੱਖਰ ਰੱਖੋ। ਅੱਖਰਾਂ ਨੂੰ ਚਿੰਨ੍ਹਾਂ ਨਾਲ ਬਦਲਣ ਨਾਲੋਂ ਲੰਬਾਈ ਵੱਧ ਮਾਇਨੇ ਰੱਖਦੀ ਹੈ।',
    tip3_t: 'ਪਾਸਵਰਡ ਮੈਨੇਜਰ ਵਰਤੋ', tip3_d: 'ਪਾਸਵਰਡ ਮੈਨੇਜਰ (ਜਿਵੇਂ ਤੁਹਾਡੇ ਫ਼ੋਨ ਜਾਂ ਬ੍ਰਾਊਜ਼ਰ ਵਿੱਚ ਬਣਿਆ) ਮਜ਼ਬੂਤ ਪਾਸਵਰਡ ਯਾਦ ਰੱਖਦਾ ਹੈ। ਤੁਹਾਨੂੰ ਸਿਰਫ਼ ਇੱਕ ਮਜ਼ਬੂਤ ਪਾਸਫ਼ਰੇਜ਼ ਯਾਦ ਰੱਖਣਾ ਹੈ।',
    tip4_t: '2-ਸਟੈਪ ਵੈਰੀਫ਼ਿਕੇਸ਼ਨ ਚਾਲੂ ਕਰੋ', tip4_d: 'ਫਿਰ ਸਿਰਫ਼ ਚੋਰੀ ਹੋਇਆ ਪਾਸਵਰਡ ਕਾਫ਼ੀ ਨਹੀਂ ਹੁੰਦਾ। ਇਸ ਨੂੰ ਈਮੇਲ, WhatsApp (ਟੂ-ਸਟੈਪ PIN), Instagram ਅਤੇ ਹੋਰ ਜ਼ਰੂਰੀ ਖਾਤਿਆਂ ’ਤੇ ਚਾਲੂ ਕਰੋ।',
    tip5_t: 'OTP ਕਦੇ ਸਾਂਝਾ ਨਾ ਕਰੋ', tip5_d: 'ਬੈਂਕ ਮੁਲਾਜ਼ਮ, ਪੁਲਿਸ, ਡਿਲੀਵਰੀ ਵਾਲੇ ਜਾਂ “ਕਸਟਮਰ ਕੇਅਰ” ਕਦੇ ਤੁਹਾਡਾ OTP, PIN ਜਾਂ ਪਾਸਵਰਡ ਨਹੀਂ ਮੰਗਦੇ। ਜੋ ਮੰਗੇ, ਉਹ ਧੋਖੇਬਾਜ਼ ਹੈ।',
    tip6_t: 'ਨਿੱਜੀ ਗੱਲਾਂ ਨਹੀਂ', tip6_d: 'ਨਾਂ, ਜਨਮ ਦਿਨ, ਫ਼ੋਨ ਨੰਬਰ, ਪਾਲਤੂ ਦਾ ਨਾਂ ਜਾਂ ਪਸੰਦੀਦਾ ਕ੍ਰਿਕਟਰ ਨਹੀਂ। ਇਹ ਸੋਸ਼ਲ ਮੀਡੀਆ ’ਤੇ ਆਸਾਨੀ ਨਾਲ ਮਿਲ ਜਾਂਦੇ ਹਨ।',
    tip7_t: 'ਸਾਂਝੇ ਕੰਪਿਊਟਰ ’ਤੇ ਸਾਵਧਾਨ', tip7_d: 'ਸਾਈਬਰ ਕੈਫ਼ੇ ਜਾਂ ਕੰਪਿਊਟਰ ਲੈਬ ਵਿੱਚ “ਪਾਸਵਰਡ ਯਾਦ ਰੱਖੋ” ’ਤੇ ਟਿੱਕ ਨਾ ਕਰੋ, ਅਤੇ ਹਮੇਸ਼ਾ ਲੌਗ ਆਊਟ ਕਰੋ।',
    tip8_t: 'ਲੀਕ ਤੋਂ ਬਾਅਦ ਬਦਲੋ', tip8_d: 'ਜੇ ਕੋਈ ਵੈੱਬਸਾਈਟ ਦੱਸੇ ਕਿ ਉਸ ਦਾ ਡਾਟਾ ਲੀਕ ਹੋਇਆ ਹੈ, ਜਾਂ ਤੁਸੀਂ ਕਿਸੇ ਨੂੰ ਪਾਸਵਰਡ ਦੱਸ ਦਿੱਤਾ, ਤਾਂ ਜਿੱਥੇ-ਜਿੱਥੇ ਵਰਤਿਆ ਸੀ, ਉੱਥੇ ਤੁਰੰਤ ਬਦਲੋ।',
    help_title: 'ਸਾਈਬਰ ਧੋਖਾ? ਤੁਰੰਤ ਮਦਦ ਲਓ',
