    inside_title: 'ଭିତରେ କ’ଣ ହେଉଛି?',
    inside_1: 'ବିକଳ୍ପ ଗଣନ୍ତୁ। ଛୋଟ ଅକ୍ଷରରେ ପ୍ରତ୍ୟେକ ସ୍ଥାନ ପାଇଁ 26ଟି ବିକଳ୍ପ; ବଡ଼ ଅକ୍ଷର, ଅଙ୍କ ଓ ଚିହ୍ନ ମିଶାଇ 95 ପର୍ଯ୍ୟନ୍ତ। ସିଧା ଗଣିତ ପ୍ରତ୍ୟେକ ଅକ୍ଷର ପାଇଁ ବିକଳ୍ପଗୁଡ଼ିକୁ ଥରେ ଗୁଣନ କରେ।',
