    inside_3: 'ଗୁଣନ କରନ୍ତୁ। ପ୍ରତ୍ୟେକ ଖଣ୍ଡର ଅନୁମାନ ପରସ୍ପର ସହ ଗୁଣନ ହୁଏ। “ବିଟ୍” ଏହାକୁ ଗଣିବାର ଛୋଟ ଉପାୟ: ପ୍ରତ୍ୟେକ ଅତିରିକ୍ତ ବିଟ୍‌ରେ ଅନୁମାନ ଦୁଇଗୁଣ ହୁଏ।',
    inside_4: 'ବେଗ ଦ୍ୱାରା ଭାଗ କରନ୍ତୁ। ଧରନ୍ତୁ ଜଣେ ଆକ୍ରମଣକାରୀ ଲୁଚାଯାଇଥିବା ପାସୱାର୍ଡର ଫାଇଲ୍ ଚୋରି କରିଛି ଓ ଶକ୍ତିଶାଳୀ ଗ୍ରାଫିକ୍ସ କାର୍ଡରେ ପ୍ରତି ସେକେଣ୍ଡରେ 1000 କୋଟି ଅନୁମାନ କରୁଛି। ୱେବସାଇଟ୍ କିଛି ଭୁଲ ଚେଷ୍ଟା ପରେ ଅଟକାଇ ଦିଏ, କିନ୍ତୁ ଚୋରି ହୋଇଥିବା ଫାଇଲ୍ ଉପରେ ପୂରା ବେଗରେ ଆକ୍ରମଣ ହୋଇପାରେ।',
