    tips_sub: 'ଏହି ପୋଷ୍ଟର କମ୍ପ୍ୟୁଟର ଲ୍ୟାବ୍ କିମ୍ବା ଶ୍ରେଣୀର ନୋଟିସ ବୋର୍ଡ ପାଇଁ ପ୍ରିଣ୍ଟ କରନ୍ତୁ।',
    tip1_t: 'ଗୋଟିଏ ପାସୱାର୍ଡ, ଗୋଟିଏ ଆକାଉଣ୍ଟ', tip1_d: 'ଗୋଟିଏ ୱେବସାଇଟ୍ ହ୍ୟାକ୍ ହେଲେ ଅପରାଧୀ ସେହି ପାସୱାର୍ଡ ଆପଣଙ୍କ ଇମେଲ୍, ସୋସିଆଲ୍ ମିଡିଆ ଓ ବ୍ୟାଙ୍କରେ ଚେଷ୍ଟା କରନ୍ତି। ଅଲଗା ପାସୱାର୍ଡ ଏହାକୁ ରୋକେ।',
    tip2_t: 'ଚତୁରତାଠାରୁ ଲମ୍ବ ଭଲ', tip2_d: '5 କିମ୍ବା ଅଧିକ ଏଲୋମେଲୋ ଶବ୍ଦ, କିମ୍ବା 12+ ଏଲୋମେଲୋ ଅକ୍ଷର ରଖନ୍ତୁ। ଅକ୍ଷରକୁ ଚିହ୍ନରେ ବଦଳାଇବାଠାରୁ ଲମ୍ବ ଅଧିକ ଜରୁରୀ।',
    tip3_t: 'ପାସୱାର୍ଡ ମ୍ୟାନେଜର୍ ବ୍ୟବହାର କରନ୍ତୁ', tip3_d: 'ପାସୱାର୍ଡ ମ୍ୟାନେଜର୍ (ଯେମିତି ଆପଣଙ୍କ ଫୋନ୍ କିମ୍ବା ବ୍ରାଉଜରରେ ଥିବା) ଶକ୍ତିଶାଳୀ ପାସୱାର୍ଡ ମନେ ରଖେ। ଆପଣଙ୍କୁ କେବଳ ଗୋଟିଏ ଶକ୍ତିଶାଳୀ ପାସଫ୍ରେଜ୍ ମନେ ରଖିବାକୁ ପଡ଼େ।',
    tip4_t: '2-ଷ୍ଟେପ୍ ଭେରିଫିକେସନ୍ ଚାଲୁ କରନ୍ତୁ', tip4_d: 'ତାପରେ କେବଳ ଚୋରି ହୋଇଥିବା ପାସୱାର୍ଡ ଯଥେଷ୍ଟ ନୁହେଁ। ଇମେଲ୍, WhatsApp (ଟୁ-ଷ୍ଟେପ୍ PIN), Instagram ଓ ଅନ୍ୟ ଜରୁରୀ ଆକାଉଣ୍ଟରେ ଏହା ଚାଲୁ କରନ୍ତୁ।',
    tip5_t: 'କେବେ OTP ସେୟାର୍ କରନ୍ତୁ ନାହିଁ', tip5_d: 'ବ୍ୟାଙ୍କ କର୍ମଚାରୀ, ପୋଲିସ୍, ଡେଲିଭରି ଲୋକ କିମ୍ବା “କଷ୍ଟମର୍ କେୟାର୍” କେବେ ଆପଣଙ୍କ OTP, PIN କିମ୍ବା ପାସୱାର୍ଡ ମାଗନ୍ତି ନାହିଁ। ଯିଏ ମାଗେ, ସେ ଠକ।',
    tip6_t: 'ବ୍ୟକ୍ତିଗତ କଥା ନୁହେଁ', tip6_d: 'ନାମ, ଜନ୍ମଦିନ, ଫୋନ୍ ନମ୍ବର, ପୋଷା ପ୍ରାଣୀର ନାମ କିମ୍ବା ପ୍ରିୟ କ୍ରିକେଟର୍ ନୁହେଁ। ଏସବୁ ସୋସିଆଲ୍ ମିଡିଆରେ ସହଜରେ ମିଳେ।',
    tip7_t: 'ସାଝା କମ୍ପ୍ୟୁଟରରେ ସାବଧାନ', tip7_d: 'ସାଇବର କାଫେ କିମ୍ବା କମ୍ପ୍ୟୁଟର ଲ୍ୟାବରେ “ପାସୱାର୍ଡ ମନେ ରଖନ୍ତୁ”ରେ ଟିକ୍ ଦିଅନ୍ତୁ ନାହିଁ, ଏବଂ ସବୁବେଳେ ଲଗ୍ ଆଉଟ୍ କରନ୍ତୁ।',
    tip8_t: 'ଲିକ୍ ପରେ ବଦଳାନ୍ତୁ', tip8_d: 'କୌଣସି ୱେବସାଇଟ୍ ଯଦି କହେ ତାର ଡାଟା ଲିକ୍ ହୋଇଛି, କିମ୍ବା ଆପଣ କାହାକୁ ପାସୱାର୍ଡ କହିଦେଲେ, ତେବେ ଯେଉଁଠି ବ୍ୟବହାର କରିଥିଲେ ସବୁଠି ତୁରନ୍ତ ବଦଳାନ୍ତୁ।',
