    how1: 'ଯେକୌଣସି ମିଛ ପାସୱାର୍ଡ ଲେଖନ୍ତୁ, କିମ୍ବା ଏକ ଉଦାହରଣରେ ଟାପ୍ କରନ୍ତୁ। ଆକ୍ରମଣକାରୀ ଚିହ୍ନିବା ଖଣ୍ଡଗୁଡ଼ିକ ଦେଖିବାକୁ “ଦେଖାନ୍ତୁ” ଦବାନ୍ତୁ।',
