    how4: 'ଶ୍ରେଣୀ କାର୍ଯ୍ୟ: ପ୍ରତ୍ୟେକ ଦଳ ବୋର୍ଡରେ 3ଟି ମିଛ ପାସୱାର୍ଡ ଲେଖନ୍ତୁ। ପୂରା ଶ୍ରେଣୀ ସେଗୁଡ଼ିକୁ ସବୁଠାରୁ ଦୁର୍ବଳରୁ ସବୁଠାରୁ ଶକ୍ତିଶାଳୀ କ୍ରମରେ ସଜାନ୍ତୁ, ତାପରେ ସ୍ମାର୍ଟବୋର୍ଡରେ ଏଠି ଯାଞ୍ଚ କରନ୍ତୁ।',
