    empty_hint: 'எழுதத் தொடங்குங்கள். சோதனை உடனே, இங்கேயே உங்கள் சாதனத்தில் நடக்கும்.',
    time_label: 'ஒரு வினாடிக்கு 1000 கோடி ஊகங்கள் செய்யும் வேகமான கணினி இதைக் கண்டுபிடிக்கும் நேரம்:',
    level0: 'மிகவும் பலவீனம்', level1: 'பலவீனம்', level2: 'பரவாயில்லை', level3: 'வலுவானது', level4: 'மிக வலுவானது',
    stat_len: 'எழுத்துகள்', stat_bits: 'பிட்கள்', stat_guesses: 'தேவையான ஊகங்கள்',
