    pieces_title: 'தாக்குபவருக்கு இது எப்படித் தெரிகிறது',
    pieces_hint: 'தாக்குபவர்கள் முதலில் முறைகளை (pattern) முயல்வார்கள். எல்லாத் துண்டுகளின் ஊகங்களையும் பெருக்கினால் மொத்தம் கிடைக்கும்.',
    pieces_hidden: 'ஒவ்வொரு துண்டின் எழுத்துகளைப் பார்க்க “காட்டு” அழுத்துங்கள்.',
    kind_common: 'பொதுவான கடவுச்சொல்', kind_word: 'ஆங்கிலச் சொல்', kind_hindi: 'இந்திச் சொல்', kind_name: 'பெயர்', kind_place: 'இடம்',
    kind_date: 'தேதி', kind_year: 'ஆண்டு', kind_seq: 'வரிசை', kind_keyboard: 'விசைப்பலகை முறை', kind_repeat: 'மீண்டும் வருவது',
