    time_universe: 'విశ్వం వయసు కంటే ఎక్కువ సమయంలో',
    inside_title: 'లోపల ఏం జరుగుతోంది?',
    inside_1: 'ఎంపికలు లెక్కించండి. చిన్న అక్షరాలతో ప్రతి స్థానానికి 26 ఎంపికలు; పెద్ద అక్షరాలు, అంకెలు, గుర్తులతో 95 వరకు. సాధారణ లెక్క ప్రతి అక్షరానికి ఎంపికలను ఒకసారి గుణిస్తుంది.',
    inside_2: 'నమూనాలు గుర్తించండి. నిజమైన దాడి చేసేవారు యాదృచ్ఛికంగా ఊహించరు. ముందుగా లీక్ అయిన సాధారణ పాస్‌వర్డ్‌లు, పదాలు, పేర్లు, తేదీలు, కీబోర్డ్ వరుసలు (qwerty), వరుసలు (1234), పునరావృతాలు, ఒకేలా కనిపించే మార్పులు (p@ssw0rd) ప్రయత్నిస్తారు. ఈ యాప్ కూడా అవే నమూనాలు వెతుకుతుంది.',
    inside_3: 'గుణించండి. ప్రతి ముక్క ఊహలు ఒకదానితో ఒకటి గుణించబడతాయి. “బిట్” వీటిని లెక్కించే చిన్న మార్గం: ప్రతి అదనపు బిట్ ఊహలను రెట్టింపు చేస్తుంది.',
    inside_4: 'వేగంతో భాగించండి. ఒక దాడి చేసేవాడు గజిబిజి చేసిన పాస్‌వర్డ్‌ల ఫైల్‌ను దొంగిలించి, శక్తివంతమైన గ్రాఫిక్స్ కార్డులతో సెకనుకు 1000 కోట్ల ఊహలు చేస్తున్నాడని అనుకుందాం. వెబ్‌సైట్లు కొన్ని తప్పు ప్రయత్నాల తర్వాత ఆపేస్తాయి, కానీ దొంగిలించిన ఫైల్‌పై పూర్తి వేగంతో దాడి చేయవచ్చు.',
    inside_5: 'ఇది ఒక అంచనా మాత్రమే. మా పదాల జాబితాలు చిన్నవి, కాబట్టి మాకు తెలియని పదాలు (భారతీయ లిపుల్లో రాసిన పదాలు కూడా) నిజానికంటే బలంగా కనిపించవచ్చు.',
    scale_title: 'బలం కొలమానం', scale_level: 'స్థాయి', scale_time: 'కనిపెట్టడానికి పట్టే సమయం',
    scale_0: '1 గంట కంటే తక్కువ', scale_1: '1 గంట నుండి 1 నెల', scale_2: '1 నెల నుండి 100 సంవత్సరాలు', scale_3: '100 సంవత్సరాల నుండి 1 కోటి సంవత్సరాలు', scale_4: '1 కోటి సంవత్సరాల కంటే ఎక్కువ',
