    time_crore: 'ಸುಮಾರು {n} ಕೋಟಿ ವರ್ಷಗಳಲ್ಲಿ',
    time_universe: 'ವಿಶ್ವದ ವಯಸ್ಸಿಗಿಂತಲೂ ಹೆಚ್ಚು ಸಮಯದಲ್ಲಿ',
    inside_title: 'ಒಳಗೆ ಏನು ನಡೆಯುತ್ತಿದೆ?',
    inside_1: 'ಆಯ್ಕೆಗಳನ್ನು ಎಣಿಸಿ. ಸಣ್ಣ ಅಕ್ಷರಗಳಿಂದ ಪ್ರತಿ ಸ್ಥಾನಕ್ಕೆ 26 ಆಯ್ಕೆಗಳು; ದೊಡ್ಡ ಅಕ್ಷರಗಳು, ಅಂಕಿಗಳು, ಚಿಹ್ನೆಗಳೊಂದಿಗೆ 95ರವರೆಗೆ. ಸರಳ ಲೆಕ್ಕ ಪ್ರತಿ ಅಕ್ಷರಕ್ಕೂ ಆಯ್ಕೆಗಳನ್ನು ಒಮ್ಮೆ ಗುಣಿಸುತ್ತದೆ.',
    inside_2: 'ಮಾದರಿಗಳನ್ನು ಗುರುತಿಸಿ. ನಿಜವಾದ ದಾಳಿಕೋರರು ಯಾದೃಚ್ಛಿಕವಾಗಿ ಊಹಿಸುವುದಿಲ್ಲ. ಮೊದಲು ಸೋರಿಕೆಯಾದ ಸಾಮಾನ್ಯ ಪಾಸ್‌ವರ್ಡ್‌ಗಳು, ಪದಗಳು, ಹೆಸರುಗಳು, ದಿನಾಂಕಗಳು, ಕೀಬೋರ್ಡ್ ಸಾಲುಗಳು (qwerty), ಅನುಕ್ರಮಗಳು (1234), ಪುನರಾವರ್ತನೆಗಳು ಮತ್ತು ಒಂದೇ ರೀತಿ ಕಾಣುವ ಬದಲಾವಣೆಗಳನ್ನು (p@ssw0rd) ಪ್ರಯತ್ನಿಸುತ್ತಾರೆ. ಈ ಆ್ಯಪ್ ಕೂಡ ಅದೇ ಮಾದರಿಗಳನ್ನು ಹುಡುಕುತ್ತದೆ.',
    inside_3: 'ಗುಣಿಸಿ. ಪ್ರತಿ ತುಂಡಿನ ಊಹೆಗಳು ಒಂದಕ್ಕೊಂದು ಗುಣಿಸಲ್ಪಡುತ್ತವೆ. “ಬಿಟ್” ಇವನ್ನು ಎಣಿಸುವ ಚಿಕ್ಕ ವಿಧಾನ: ಪ್ರತಿ ಹೆಚ್ಚುವರಿ ಬಿಟ್ ಊಹೆಗಳನ್ನು ಎರಡು ಪಟ್ಟು ಮಾಡುತ್ತದೆ.',
    inside_4: 'ವೇಗದಿಂದ ಭಾಗಿಸಿ. ಒಬ್ಬ ದಾಳಿಕೋರ ಗೊಂದಲಗೊಳಿಸಿದ ಪಾಸ್‌ವರ್ಡ್‌ಗಳ ಫೈಲ್ ಕದ್ದು, ಶಕ್ತಿಶಾಲಿ ಗ್ರಾಫಿಕ್ಸ್ ಕಾರ್ಡ್‌ಗಳಿಂದ ಪ್ರತಿ ಸೆಕೆಂಡಿಗೆ 1000 ಕೋಟಿ ಊಹೆ ಮಾಡುತ್ತಿದ್ದಾನೆ ಎಂದುಕೊಳ್ಳಿ. ವೆಬ್‌ಸೈಟ್‌ಗಳು ಕೆಲವು ತಪ್ಪು ಪ್ರಯತ್ನಗಳ ನಂತರ ತಡೆಯುತ್ತವೆ, ಆದರೆ ಕದ್ದ ಫೈಲ್ ಮೇಲೆ ಪೂರ್ಣ ವೇಗದಲ್ಲಿ ದಾಳಿ ಮಾಡಬಹುದು.',
    inside_5: 'ಇದು ಕೇವಲ ಅಂದಾಜು. ನಮ್ಮ ಪದಪಟ್ಟಿಗಳು ಚಿಕ್ಕವು, ಆದ್ದರಿಂದ ನಮಗೆ ಗೊತ್ತಿಲ್ಲದ ಪದಗಳು (ಭಾರತೀಯ ಲಿಪಿಗಳಲ್ಲಿ ಬರೆದ ಪದಗಳೂ) ನಿಜಕ್ಕಿಂತ ಬಲವಾಗಿ ಕಾಣಬಹುದು.',
    scale_title: 'ಶಕ್ತಿಯ ಅಳತೆಪಟ್ಟಿ', scale_level: 'ಮಟ್ಟ', scale_time: 'ಪತ್ತೆಹಚ್ಚಲು ಬೇಕಾದ ಸಮಯ',
    scale_0: '1 ಗಂಟೆಗಿಂತ ಕಡಿಮೆ', scale_1: '1 ಗಂಟೆಯಿಂದ 1 ತಿಂಗಳು', scale_2: '1 ತಿಂಗಳಿನಿಂದ 100 ವರ್ಷ', scale_3: '100 ವರ್ಷದಿಂದ 1 ಕೋಟಿ ವರ್ಷ', scale_4: '1 ಕೋಟಿ ವರ್ಷಕ್ಕಿಂತ ಹೆಚ್ಚು',
    gen_title: 'ಪಾಸ್‌ಫ್ರೇಸ್ ಮಾಡಿ',
    gen_intro: 'ಪಾಸ್‌ಫ್ರೇಸ್ ಎಂದರೆ ಕೆಲವು ಯಾದೃಚ್ಛಿಕ ಪದಗಳನ್ನು ಜೋಡಿಸಿ ಮಾಡಿದ್ದು. ಇದು ಉದ್ದವಿರುವುದರಿಂದ ಊಹಿಸಲು ಕಷ್ಟ, ಆದರೆ ನೆನಪಿಡಲು ಸುಲಭ.',
    gen_new: 'ಹೊಸ ಪಾಸ್‌ಫ್ರೇಸ್', gen_test: 'ಇದನ್ನು ಪರೀಕ್ಷಿಸು', gen_aria: 'ನಿಮ್ಮ ಪಾಸ್‌ಫ್ರೇಸ್',
    opt_words: 'ಪದಗಳ ಸಂಖ್ಯೆ', opt_list: 'ಪದಪಟ್ಟಿ', list_en: 'ಇಂಗ್ಲಿಷ್', list_hi: 'ಹಿಂದಿ (ರೋಮನ್ ಅಕ್ಷರಗಳಲ್ಲಿ)', list_both: 'ಎರಡೂ',
    opt_sep: 'ಪದಗಳ ನಡುವೆ', sep_space: 'ಸ್ಪೇಸ್', sep_none: 'ಏನೂ ಇಲ್ಲ',
    opt_number: 'ಒಂದು ಸಂಖ್ಯೆ ಸೇರಿಸು', opt_caps: 'ಮೊದಲ ಅಕ್ಷರ ದೊಡ್ಡದು',
    gen_each: '{w} ಪದಗಳಲ್ಲಿ ಪ್ರತಿಯೊಂದನ್ನು {N} ಪದಗಳ ಪಟ್ಟಿಯಿಂದ ಯಾದೃಚ್ಛಿಕವಾಗಿ ಆರಿಸಲಾಗುತ್ತದೆ.',
    gen_num: 'ಸಂಖ್ಯೆ (10 ರಿಂದ 99) 90 ಆಯ್ಕೆಗಳನ್ನು ಸೇರಿಸುತ್ತದೆ, ಅದು {p} ಸ್ಥಾನಗಳಲ್ಲಿ ಯಾವುದರಲ್ಲಾದರೂ ಬರಬಹುದು.',
    gen_total: 'ಒಟ್ಟು: {g} ಸಾಧ್ಯ ಪಾಸ್‌ಫ್ರೇಸ್‌ಗಳು = {bits} ಬಿಟ್‌ಗಳು.',
    gen_random_note: 'ಪದಗಳನ್ನು ನಿಮ್ಮ ಬ್ರೌಸರ್‌ನ ಸುರಕ್ಷಿತ ಯಾದೃಚ್ಛಿಕ ಜನರೇಟರ್ ಆರಿಸುತ್ತದೆ, ಮನುಷ್ಯರಲ್ಲ; ಆದ್ದರಿಂದ ಊಹಿಸಬಹುದಾದ ಮಾದರಿ ಇರುವುದಿಲ್ಲ.',
    gen_memory_tip: 'ನೆನಪಿಡಲು, ಈ ಪದಗಳಿಂದ ಒಂದು ತಮಾಷೆಯ ಚಿತ್ರ ಅಥವಾ ಚಿಕ್ಕ ಕಥೆಯನ್ನು ಕಲ್ಪಿಸಿಕೊಳ್ಳಿ.',
    gen_screen_warn: 'ಬೇರೆಯವರು ಪರದೆಯ ಮೇಲೆ ನೋಡಿದ ಪಾಸ್‌ಫ್ರೇಸ್ ಬಳಸಬೇಡಿ. ನಿಮ್ಮ ನಿಜವಾದದ್ದನ್ನು ಏಕಾಂತದಲ್ಲಿ ಮಾಡಿ.',
    quiz_title: 'ಯಾವ ಪಾಸ್‌ವರ್ಡ್ ಹೆಚ್ಚು ಬಲವಾದದ್ದು?',
    quiz_progress: 'ಪ್ರಶ್ನೆ {n} / {total}',
