    quiz_print: 'വർക്ക്‌ഷീറ്റ് പ്രിന്റ് ചെയ്യൂ',
    quiz_perfect: 'ഗംഭീരം! നിങ്ങൾ ഒരു സൈബർ സുരക്ഷാ വിദഗ്ധനെപ്പോലെ ചിന്തിക്കുന്നു.',
    quiz_good: 'നന്നായി! തെറ്റിയവയുടെ പാഠങ്ങൾ വീണ്ടും വായിക്കൂ.',
    quiz_keep: 'പരിശീലനം തുടരൂ: പേരുകൾ, തീയതികൾ, സാധാരണ വാക്കുകൾ, ഒരുപോലെ തോന്നുന്ന മാറ്റങ്ങൾ ശ്രദ്ധിക്കൂ.',
    ws_title: 'വർക്ക്‌ഷീറ്റ്: ഏത് പാസ്‌വേഡാണ് കൂടുതൽ ശക്തം?',
    ws_name: 'പേര്: ____________________   ക്ലാസ്: ________   തീയതി: __________',
    ws_instr: 'ഓരോ ജോടിയിലും ശക്തമായ പാസ്‌വേഡിൽ അടയാളമിടൂ. പിന്നെ ഒരു കാരണം എഴുതൂ.',
    ws_why: 'എന്തുകൊണ്ട്?',
    ws_key: 'ഉത്തരസൂചിക (അധ്യാപകർക്ക്)',
    tips_title: 'പാസ്‌വേഡ് സുരക്ഷാ നിയമങ്ങൾ',
    tips_sub: 'ഈ പോസ്റ്റർ കമ്പ്യൂട്ടർ ലാബിനോ ക്ലാസിലെ നോട്ടീസ് ബോർഡിനോ വേണ്ടി പ്രിന്റ് ചെയ്യൂ.',
    tip1_t: 'ഒരു പാസ്‌വേഡ്, ഒരു അക്കൗണ്ട്', tip1_d: 'ഒരു വെബ്സൈറ്റ് ഹാക്ക് ചെയ്യപ്പെട്ടാൽ, കുറ്റവാളികൾ അതേ പാസ്‌വേഡ് നിങ്ങളുടെ ഇമെയിൽ, സോഷ്യൽ മീഡിയ, ബാങ്ക് എന്നിവയിൽ പരീക്ഷിക്കും. വ്യത്യസ്ത പാസ്‌വേഡുകൾ ഇത് തടയും.',
    tip2_t: 'സൂത്രത്തേക്കാൾ നല്ലത് നീളം', tip2_d: '5-ഓ അതിലധികമോ ക്രമരഹിത വാക്കുകൾ, അല്ലെങ്കിൽ 12+ ക്രമരഹിത അക്ഷരങ്ങൾ ഉപയോഗിക്കൂ. അക്ഷരങ്ങളെ ചിഹ്നങ്ങളാക്കുന്നതിനേക്കാൾ പ്രധാനം നീളമാണ്.',
    tip3_t: 'പാസ്‌വേഡ് മാനേജർ ഉപയോഗിക്കൂ', tip3_d: 'പാസ്‌വേഡ് മാനേജർ (നിങ്ങളുടെ ഫോണിലോ ബ്രൗസറിലോ ഉള്ളത് പോലെ) ശക്തമായ പാസ്‌വേഡുകൾ ഓർത്തുവെക്കും. നിങ്ങൾ ഒരു ശക്തമായ പാസ്‌ഫ്രേസ് മാത്രം ഓർത്താൽ മതി.',
    tip4_t: '2-ഘട്ട പരിശോധന ഓണാക്കൂ', tip4_d: 'അപ്പോൾ മോഷ്ടിച്ച പാസ്‌വേഡ് മാത്രം മതിയാകില്ല. ഇമെയിൽ, WhatsApp (ടു-സ്റ്റെപ് PIN), Instagram, മറ്റ് പ്രധാന അക്കൗണ്ടുകൾ എന്നിവയിൽ ഇത് ഓണാക്കൂ.',
    tip5_t: 'ഒരിക്കലും OTP പങ്കിടരുത്', tip5_d: 'ബാങ്ക് ജീവനക്കാർ, പോലീസ്, ഡെലിവറിക്കാർ, “കസ്റ്റമർ കെയർ” ആരും ഒരിക്കലും നിങ്ങളുടെ OTP, PIN, പാസ്‌വേഡ് ചോദിക്കില്ല. ചോദിക്കുന്നവർ തട്ടിപ്പുകാരാണ്.',
    tip6_t: 'വ്യക്തിപരമായവ വേണ്ട', tip6_d: 'പേരുകൾ, ജന്മദിനം, ഫോൺ നമ്പർ, വളർത്തുമൃഗത്തിന്റെ പേര്, ഇഷ്ട ക്രിക്കറ്റർ എന്നിവ വേണ്ട. ഇവ സോഷ്യൽ മീഡിയയിൽ എളുപ്പത്തിൽ കിട്ടും.',
    tip7_t: 'പങ്കിട്ട കമ്പ്യൂട്ടറിൽ ശ്രദ്ധ', tip7_d: 'സൈബർ കഫേയിലോ കമ്പ്യൂട്ടർ ലാബിലോ “പാസ്‌വേഡ് ഓർക്കുക” ടിക്ക് ചെയ്യരുത്, എപ്പോഴും ലോഗ് ഔട്ട് ചെയ്യൂ.',
    tip8_t: 'ചോർച്ചയ്ക്ക് ശേഷം മാറ്റൂ', tip8_d: 'ഒരു വെബ്സൈറ്റ് തങ്ങളുടെ ഡേറ്റ ചോർന്നെന്ന് പറഞ്ഞാൽ, അല്ലെങ്കിൽ നിങ്ങൾ ആരോടെങ്കിലും പാസ്‌വേഡ് പറഞ്ഞുപോയാൽ, അത് ഉപയോഗിച്ച എല്ലായിടത്തും ഉടൻ മാറ്റൂ.',
    help_title: 'സൈബർ തട്ടിപ്പാണോ? ഉടൻ സഹായം തേടൂ',
    help_text: '1930 (ദേശീയ സൈബർ ക്രൈം ഹെൽപ്‌ലൈൻ) വിളിക്കൂ അല്ലെങ്കിൽ cybercrime.gov.in ൽ പരാതി നൽകൂ',
    print_poster: 'പോസ്റ്റർ പ്രിന്റ് ചെയ്യൂ',
    howto_title: 'എങ്ങനെ ഉപയോഗിക്കാം / ക്ലാസിനുള്ള ആശയങ്ങൾ',
    how1: 'ഏതെങ്കിലും സാങ്കൽപ്പിക പാസ്‌വേഡ് എഴുതൂ, അല്ലെങ്കിൽ ഒരു ഉദാഹരണത്തിൽ തൊടൂ. ആക്രമണകാരി തിരിച്ചറിയുന്ന കഷണങ്ങൾ കാണാൻ “കാണിക്കുക” അമർത്തൂ.',
    how2: '“പ്രശ്നങ്ങൾ” വായിക്കൂ, പാസ്‌വേഡ് മാറ്റൂ, ഊഹിക്കാനുള്ള സമയം എങ്ങനെ കൂടുന്നു എന്ന് കാണൂ.',
    how3: 'പാസ്‌ഫ്രേസ് മേക്കറിൽ വാക്കുകളുടെ എണ്ണം തിരഞ്ഞെടുത്ത് “പുതിയ പാസ്‌ഫ്രേസ്” അമർത്തൂ. പിന്നെ “ഇത് പരിശോധിക്കൂ” അമർത്തൂ.',
    how4: 'ക്ലാസ് പ്രവർത്തനം: ഓരോ ഗ്രൂപ്പും ബോർഡിൽ 3 സാങ്കൽപ്പിക പാസ്‌വേഡുകൾ എഴുതട്ടെ. ക്ലാസ് മുഴുവൻ അവയെ ഏറ്റവും ദുർബലം മുതൽ ഏറ്റവും ശക്തം വരെ ക്രമീകരിച്ച്, പിന്നെ സ്മാർട്ട്ബോർഡിൽ ഇവിടെ പരിശോധിക്കട്ടെ.',
    how5: 'ജോടികളായി ക്വിസ് കളിക്കൂ, അല്ലെങ്കിൽ ഹോംവർക്കിനായി വർക്ക്‌ഷീറ്റ് പ്രിന്റ് ചെയ്യൂ.',
    how6: 'കമ്പ്യൂട്ടർ ലാബിനോ നോട്ടീസ് ബോർഡിനോ വേണ്ടി “സുരക്ഷാ നുറുങ്ങുകൾ” പോസ്റ്റർ പ്രിന്റ് ചെയ്യൂ.'
